import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { deleteFileLink } from "../handlers/deleteFileLink";
import type { ApiError } from "../runtime/client";
import type { DeleteFileLinkRequest } from "../types/DeleteFileLinkRequest";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof deleteFileLink>>;
type Vars = { spacePk: SpacePartition; req: DeleteFileLinkRequest };

export function useDeleteFileLink(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => deleteFileLink(vars.spacePk, vars.req),
    ...options,
  });
}
